{"path":"lib/main.dart","content":"import 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\n\nvoid main() {\n  WidgetsFlutterBinding.ensureInitialized();\n  runApp(const CodeDoctorApp());\n}\n\n/// Root Application\nclass CodeDoctorApp extends StatelessWidget {\n  const CodeDoctorApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      title: 'طبيب الأكواد | مشروعي',\n      debugShowCheckedModeBanner: false,\n      themeMode: ThemeMode.dark,\n      theme: AppTheme.darkTheme,\n      builder: (context, child) {\n        // Enforce RTL direction for natural Arabic experience\n        return Directionality(\n          textDirection: TextDirection.rtl,\n          child: child!,\n        );\n      },\n      home: const AuthWrapper(),\n    );\n  }\n}\n\n// ============================================================================\n// THEME DEFINITIONS\n// ============================================================================\nclass AppTheme {\n  static final ThemeData darkTheme = ThemeData(\n    brightness: Brightness.dark,\n    scaffoldBackgroundColor: const Color(0xFF090D16),\n    primaryColor: const Color(0xFF10B981),\n    colorScheme: const ColorScheme.dark(\n      primary: Color(0xFF10B981),\n      secondary: Color(0xFF06B6D4),\n      surface: Color(0xFF131B2E),\n      error: Color(0xFFEF4444),\n      onPrimary: Colors.black,\n      onSurface: Color(0xFFE2E8F0),\n    ),\n    appBarTheme: const AppBarTheme(\n      backgroundColor: Color(0xFF0F172A),\n      elevation: 0,\n      centerTitle: true,\n      iconTheme: IconThemeData(color: Color(0xFF38BDF8)),\n      titleTextStyle: TextStyle(\n        color: Colors.white,\n        fontSize: 18,\n        fontWeight: FontWeight.bold,\n        fontFamily: 'sans-serif',\n      ),\n    ),\n    cardTheme: CardTheme(\n      color: const Color(0xFF131B2E),\n      elevation: 2,\n      shape: RoundedRectangleBorder(\n        borderRadius: BorderRadius.circular(16),\n        side: const BorderSide(color: Color(0xFF1E293B)),\n      ),\n    ),\n    fontFamily: 'sans-serif',\n  );\n}\n\n// ============================================================================\n// MODELS & GLOBAL STATE\n// ============================================================================\nclass CodeFile {\n  String id;\n  String name;\n  String language;\n  String content;\n  DateTime updatedAt;\n\n  CodeFile({\n    required this.id,\n    required this.name,\n    required this.language,\n    required this.content,\n    required this.updatedAt,\n  });\n}\n\nclass Project {\n  String id;\n  String title;\n  String description;\n  List<CodeFile> files;\n  DateTime createdAt;\n\n  Project({\n    required this.id,\n    required this.title,\n    required this.description,\n    required this.files,\n    required this.createdAt,\n  });\n}\n\nclass ReferenceCardItem {\n  final String title;\n  final String language;\n  final String errorSnippet;\n  final String fixedSnippet;\n  final String explanation;\n  final String tip;\n\n  const ReferenceCardItem({\n    required this.title,\n    required this.language,\n    required this.errorSnippet,\n    required this.fixedSnippet,\n    required this.explanation,\n    required this.tip,\n  });\n}\n\nclass ChatMessage {\n  final String id;\n  final String text;\n  final bool isUser;\n  final String? codeSnippet;\n  final DateTime timestamp;\n\n  ChatMessage({\n    required this.id,\n    required this.text,\n    required this.isUser,\n    this.codeSnippet,\n    required this.timestamp,\n  });\n}\n\n/// App repository holding runtime sample projects & cheat sheets\nclass AppDataService {\n  static final AppDataService _instance = AppDataService._internal();\n  factory AppDataService() => _instance;\n  AppDataService._internal();\n\n  bool isAuthenticated = false;\n  String userEmail = 'dev.ahmed@example.com';\n\n  final List<Project> projects = [\n    Project(\n      id: 'p1',\n      title: 'متجر دارت المحمول',\n      description: 'واجهة متجر إلكتروني باستخدام Flutter مع سلة تسوق ديناميكية',\n      createdAt: DateTime.now().subtract(const Duration(days: 3)),\n      files: [\n        CodeFile(\n          id: 'f1',\n          name: 'cart_provider.dart',\n          language: 'Dart',\n          content: '''class CartProvider with ChangeNotifier {\n  final List<String> _items = [];\n  List<String> get items => _items;\n\n  void addItem(String item) {\n    _items.add(item);\n    notifyListeners();\n  }\n}''',\n          updatedAt: DateTime.now().subtract(const Duration(hours: 4)),\n        ),\n        CodeFile(\n          id: 'f2',\n          name: 'main.dart',\n          language: 'Dart',\n          content: '''void main() {\n  runApp(const MyApp());\n}''',\n          updatedAt: DateTime.now().subtract(const Duration(days: 1)),\n        ),\n      ],\n    ),\n    Project(\n      id: 'p2',\n      title: 'محلل بيانات بايثون',\n      description: 'نظام لاستخراج الإحصائيات وتحليل نصوص المدونات',\n      createdAt: DateTime.now().subtract(const Duration(days: 6)),\n      files: [\n        CodeFile(\n          id: 'f3',\n          name: 'sentiment_analyser.py',\n          language: 'Python',\n          content: '''def analyze_text(text):\n    words = text.split()\n    # خطأ متعمد لاختبار التحليل\n    counts = {}\n    for w in words:\n        counts[w] = counts.get(w, 0) + 1\n    return counts''',\n          updatedAt: DateTime.now().subtract(const Duration(days: 2)),\n        ),\n      ],\n    ),\n  ];\n\n  final List<ReferenceCardItem> referenceCards = const [\n    ReferenceCardItem(\n      title: 'Null Check Operator Used On A Null Value',\n      language: 'Dart',\n      errorSnippet: 'String? name;\nprint(name!.length); // Crash!',\n      fixedSnippet: 'String? name;\nprint(name?.length ?? 0);',\n      explanation:\n          'حدث الخطأ لأنك استخدمت معامل التأكيد (!) على متغير قيمته الفعلية null، مما تسبب في انهيار التطبيق.',\n      tip: 'استخدم دائماً مشغل الأمان (?.) أو وفّر قيمة بديلة عبر (??).',\n    ),\n    ReferenceCardItem(\n      title: 'IndexError: list index out of range',\n      language: 'Python',\n      errorSnippet: 'items = [1, 2, 3]\nprint(items[5])',\n      fixedSnippet: 'items = [1, 2, 3]\nif len(items) > 5:\n    print(items[5])\nelse:\n    print(\"العنصر غير موجود\")',\n      explanation:\n          'محاولة قراءة فهرس يتجاوز عدد العناصر الفعلية للمصفوفة. يبدأ الترقيم دائماً من الصفر.',\n      tip: 'تحقق من طول المصفوفة بواسطة len() قبل الوصول المباشر.',\n    ),\n    ReferenceCardItem(\n      title: 'Unhandled Promise Rejection / TypeError',\n      language: 'JavaScript',\n      errorSnippet: 'fetch(\"/api/user\")\n  .then(res => res.json())\n  .then(data => console.log(data.profile.name));',\n      fixedSnippet: 'fetch(\"/api/user\")\n  .then(res => res.json())\n  .then(data => console.log(data?.profile?.name))\n  .catch(err => console.error(\"فشل الطلب:\", err));',\n      explanation:\n          'إذا كان الكائن profile غير معرف أو فشلت الشبكة، ينهار الكود دون وجود كتلة catch.',\n      tip: 'اعتمد على Optional Chaining (?.) وأضف دائماً معالج أخطاء .catch().',\n    ),\n  ];\n}\n\n// ============================================================================\n// AUTH WRAPPER & LOGIN SCREEN\n// ============================================================================\nclass AuthWrapper extends StatefulWidget {\n  const AuthWrapper({super.key});\n\n  @override\n  State<AuthWrapper> createState() => _AuthWrapperState();\n}\n\nclass _AuthWrapperState extends State<AuthWrapper> {\n  @override\n  Widget build(BuildContext context) {\n    if (AppDataService().isAuthenticated) {\n      return const MainDashboardScreen();\n    }\n    return LoginScreen(\n      onLoginSuccess: () {\n        setState(() {\n          AppDataService().isAuthenticated = true;\n        });\n      },\n    );\n  }\n}\n\nclass LoginScreen extends StatefulWidget {\n  final VoidCallback onLoginSuccess;\n  const LoginScreen({super.key, required this.onLoginSuccess});\n\n  @override\n  State<LoginScreen> createState() => _LoginScreenState();\n}\n\nclass _LoginScreenState extends State<LoginScreen> {\n  final _emailController = TextEditingController(text: 'ahmed.dev@cloud.io');\n  final _passwordController = TextEditingController(text: '••••••••');\n  bool _isLoading = false;\n\n  void _simulateLogin() async {\n    setState(() => _isLoading = true);\n    await Future.delayed(const Duration(milliseconds: 700));\n    setState(() => _isLoading = false);\n    AppDataService().userEmail = _emailController.text.trim();\n    widget.onLoginSuccess();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: Container(\n        decoration: const BoxDecoration(\n          gradient: LinearGradient(\n            begin: Alignment.topCenter,\n            end: Alignment.bottomCenter,\n            colors: [Color(0xFF0F172A), Color(0xFF090D16)],\n          ),\n        ),\n        child: Center(\n          child: SingleChildScrollView(\n            padding: const EdgeInsets.symmetric(horizontal: 24),\n            child: Column(\n              mainAxisAlignment: MainAxisAlignment.center,\n              children: [\n                // Tech Icon & Badge\n                Container(\n                  padding: const EdgeInsets.all(18),\n                  decoration: BoxDecoration(\n                    shape: BoxShape.circle,\n                    color: const Color(0xFF10B981).withOpacity(0.15),\n                    border: Border.all(color: const Color(0xFF10B981), width: 1.5),\n                  ),\n                  child: const Icon(\n                    Icons.code_rounded,\n                    size: 64,\n                    color: Color(0xFF10B981),\n                  ),\n                ),\n                const SizedBox(height: 20),\n                const Text(\n                  'طبيب الأكواد الذكي',\n                  style: TextStyle(\n                    fontSize: 26,\n                    fontWeight: FontWeight.bold,\n                    color: Colors.white,\n                    letterSpacing: 0.5,\n                  ),\n                ),\n                const SizedBox(height: 8),\n                const Text(\n                  'فحص وتصحيح الأخطاء البرمجية فوراً مع شروحات عربية',\n                  textAlign: TextAlign.center,\n                  style: TextStyle(\n                    fontSize: 14,\n                    color: Color(0xFF94A3B8),\n                  ),\n                ),\n                const SizedBox(height: 36),\n\n                // Form Card\n                Card(\n                  child: Padding(\n                    padding: const EdgeInsets.all(20),\n                    child: Column(\n                      children:\n                          [\n                        TextField(\n                          controller: _emailController,\n                          keyboardType: TextInputType.emailAddress,\n                          decoration: InputDecoration(\n                            labelText: 'البريد الإلكتروني',\n                            prefixIcon: const Icon(Icons.email_outlined, color: Color(0xFF06B